sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');

/* ==========================================================================
   Campus Food Services Assistant — all styles scoped under .cfsa-page
   ========================================================================== */

.cfsa-page {
  --ca-navy: #0D0D1A;
  --ca-navy-2: #11111F;
  --ca-ink: #171725;
  --ca-gray: #6B7280;
  --ca-line: #E7E8EF;
  --ca-orange: #FF5A3C;
  --ca-red: #F5372A;
  --ca-purple: #6C63FF;
  --ca-green: #16A672;
  --ca-bg-soft: #F7F8FA;
  --ca-font-head: 'Sora', 'Trebuchet MS', sans-serif;
  --ca-font-body: 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  --ca-shadow: 0 18px 44px -18px rgba(23, 23, 37, 0.14);
  font-family: var(--ca-font-body);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ca-ink);
  background: #FFFFFF;
  width: 100%;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

.cfsa-page *,
.cfsa-page *::before,
.cfsa-page *::after { box-sizing: border-box; }

.cfsa-page h1, .cfsa-page h2, .cfsa-page h3, .cfsa-page h4,
.cfsa-page p, .cfsa-page ul, .cfsa-page ol, .cfsa-page figure { margin: 0; padding: 0; }
.cfsa-page ul, .cfsa-page ol { list-style: none; }
.cfsa-page a { text-decoration: none; color: inherit; }
.cfsa-page h1, .cfsa-page h2, .cfsa-page h3 { font-family: var(--ca-font-head); }
.cfsa-page svg { display: inline-block; vertical-align: middle; }
.cfsa-page section { scroll-margin-top: 90px; }
.cfsa-page ::selection { background: rgba(255, 90, 60, 0.22); }
.cfsa-page a:focus-visible { outline: 2px solid var(--ca-orange); outline-offset: 2px; border-radius: 4px; }

/* ---------- Layout helpers ---------- */
.cfsa-page .ca-container { max-width: 1180px; margin: 0 auto; padding: 0 24px; }
.cfsa-page .ca-sec { padding: 100px 0; }

.cfsa-page .ca-sec-head { max-width: 680px; margin: 0 auto 56px; text-align: center; }
.cfsa-page .ca-label {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--ca-font-body); font-weight: 700; font-size: 0.74rem;
  letter-spacing: 0.18em; text-transform: uppercase; color: var(--ca-orange); margin-bottom: 16px;
}
.cfsa-page .ca-label::before,
.cfsa-page .ca-label::after { content: ""; width: 22px; height: 2px; border-radius: 2px; background: currentColor; opacity: 0.45; }
.cfsa-page .ca-h2 {
  font-size: clamp(1.85rem, 1.2rem + 2.3vw, 2.9rem); font-weight: 800;
  letter-spacing: -0.02em; line-height: 1.12; color: var(--ca-ink);
}
.cfsa-page .ca-on-dark .ca-h2 { color: #FFFFFF; }
.cfsa-page .ca-lead { margin-top: 16px; font-size: 1.05rem; line-height: 1.65; color: var(--ca-gray); }
.cfsa-page .ca-on-dark .ca-lead { color: rgba(255, 255, 255, 0.62); }

/* ---------- Gradient text ---------- */
.cfsa-page .ca-grad-text { color: #FF5A3C; }
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .cfsa-page .ca-grad-text {
    background: linear-gradient(92deg, #FF8A50 0%, #FF4B35 55%, #F5372A 100%);
    -webkit-background-clip: text; background-clip: text;
    color: rgba(0, 0, 0, 0); -webkit-text-fill-color: transparent;
  }
}

/* ---------- Buttons ---------- */
.cfsa-page .ca-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  font-family: var(--ca-font-body); font-weight: 700; font-size: 0.95rem; line-height: 1;
  border-radius: 999px; padding: 15px 28px; border: 1px solid transparent; cursor: pointer;
  white-space: nowrap; transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease, border-color 0.25s ease, color 0.25s ease;
}
.cfsa-page .ca-btn-sm { padding: 11px 20px; font-size: 0.85rem; }
.cfsa-page .ca-btn-lg { padding: 17px 32px; font-size: 1rem; }
.cfsa-page .ca-btn-primary {
  color: #FFFFFF; background: linear-gradient(135deg, #FF6A3D, #F5372A);
  box-shadow: 0 10px 24px -10px rgba(245, 55, 42, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.22);
}
.cfsa-page .ca-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 18px 34px -12px rgba(245, 55, 42, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.22); }
.cfsa-page .ca-btn-ghost { color: #FFFFFF; background: rgba(255, 255, 255, 0.04); border-color: rgba(255, 255, 255, 0.26); }
.cfsa-page .ca-btn-ghost:hover { transform: translateY(-2px); background: rgba(255, 255, 255, 0.1); border-color: rgba(255, 255, 255, 0.5); }
.cfsa-page .ca-btn-dark { color: #FFFFFF; background: var(--ca-ink); box-shadow: 0 14px 28px -14px rgba(23, 23, 37, 0.55); }
.cfsa-page .ca-btn-dark:hover { transform: translateY(-2px); box-shadow: 0 20px 36px -16px rgba(23, 23, 37, 0.6); }

/* ---------- Shared accent tiles ---------- */
.cfsa-page .acc-orange { --acc: #FF5A3C; --acc-soft: rgba(255, 90, 60, 0.10); --acc-line: rgba(255, 90, 60, 0.38); }
.cfsa-page .acc-purple { --acc: #6C63FF; --acc-soft: rgba(108, 99, 255, 0.10); --acc-line: rgba(108, 99, 255, 0.35); }
.cfsa-page .acc-red    { --acc: #F5372A; --acc-soft: rgba(245, 55, 42, 0.08);  --acc-line: rgba(245, 55, 42, 0.32); }
.cfsa-page .acc-teal   { --acc: #12B5A5; --acc-soft: rgba(18, 181, 165, 0.10); --acc-line: rgba(18, 181, 165, 0.35); }
.cfsa-page .ca-ico-tile {
  flex: none; width: 46px; height: 46px; border-radius: 13px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--acc-soft); color: var(--acc);
}

/* ---------- Shared small parts ---------- */
.cfsa-page .ca-dot-live {
  flex: none; width: 8px; height: 8px; border-radius: 50%;
  background: #2ED397; animation: caPing 2.2s ease-out infinite;
}
.cfsa-page .ca-trend { display: inline-flex; align-items: center; gap: 4px; font-size: 10px; font-weight: 800; }
.cfsa-page .ca-trend i { width: 0; height: 0; border-left: 4px solid transparent; border-right: 4px solid transparent; }
.cfsa-page .ca-trend.up i { border-bottom: 6px solid currentColor; }
.cfsa-page .ca-trend.down i { border-top: 6px solid currentColor; }
.cfsa-page .ca-trend.pos { color: #16A672; }
.cfsa-page .ca-trend.neg { color: #E5484D; }
.cfsa-page .ca-cbar { display: block; height: 5px; border-radius: 99px; background: #EFF1F6; overflow: hidden; margin-top: 5px; }
.cfsa-page .ca-cbar i { display: block; height: 100%; border-radius: 99px; }
.cfsa-page .ca-cbar-w { width: 92px; }
.cfsa-page .ca-pill { display: inline-block; font-style: normal; font-size: 9px; font-weight: 800; letter-spacing: 0.02em; padding: 4px 10px; border-radius: 999px; }
.cfsa-page .ca-pill-ok { background: #E2F6EC; color: #12805C; }
.cfsa-page .ca-pill-live { background: #FFE9E2; color: #E04B2F; }
.cfsa-page .ca-pill-queue { background: #EEF0F5; color: #7A8090; }
.cfsa-page .ca-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.cfsa-page .ca-tag { font-size: 0.72rem; font-weight: 700; color: #5D6270; background: #F3F4F8; border: 1px solid #E8EAF1; padding: 5px 10px; border-radius: 999px; }

.cfsa-page .ca-check-list { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 18px; }
.cfsa-page .ca-check-list li { position: relative; padding-left: 24px; color: #454A5A; font-size: 0.9rem; font-weight: 600; line-height: 1.45; }
.cfsa-page .ca-check-list li::before {
  content: ""; position: absolute; left: 0; top: 0.3em; width: 13px; height: 7px;
  border-left: 2px solid var(--ca-orange); border-bottom: 2px solid var(--ca-orange);
  transform: rotate(-45deg);
}
.cfsa-page .ca-check-dark li { color: rgba(255, 255, 255, 0.78); }

/* ==========================================================================
   HEADER
   ========================================================================== */
.cfsa-page .ca-nav-toggle { position: absolute; opacity: 0; width: 1px; height: 1px; margin: -1px; pointer-events: none; }
.cfsa-page .ca-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(255, 255, 255, 0.94);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(23, 23, 37, 0.07);
}
.cfsa-page .ca-header-inner { display: flex; align-items: center; justify-content: space-between; gap: 20px; height: 72px; }
.cfsa-page .ca-logo { display: inline-flex; align-items: center; gap: 10px; flex: none; }
.cfsa-page .ca-logo-text { font-family: var(--ca-font-head); font-weight: 800; font-size: 1.3rem; letter-spacing: -0.03em; color: var(--ca-ink); }
.cfsa-page .ca-logo-light .ca-logo-text { color: #FFFFFF; }
.cfsa-page .ca-logo-mark { position: relative; width: 26px; height: 26px; flex: none; }
.cfsa-page .ca-logo-mark::before {
  content: ""; position: absolute; inset: 0; transform: rotate(45deg); border-radius: 7px;
  background: linear-gradient(135deg, #FF8A50, #F5372A);
  box-shadow: 0 6px 14px -4px rgba(245, 55, 42, 0.55);
}
.cfsa-page .ca-logo-mark::after { content: ""; position: absolute; inset: 7px; transform: rotate(45deg); border-radius: 2.5px; background: #FFFFFF; opacity: 0.94; }
.cfsa-page .ca-logo-mark-lg { width: 42px; height: 42px; }
.cfsa-page .ca-logo-mark-lg::after { inset: 11px; border-radius: 4px; }

.cfsa-page .ca-nav-links { display: flex; align-items: center; gap: 2px; }
.cfsa-page .ca-nav-link {
  padding: 9px 13px; border-radius: 9px;
  font-family: var(--ca-font-body); font-weight: 600; font-size: 0.875rem; color: #3F4152;
  transition: color 0.2s ease, background 0.2s ease;
}
.cfsa-page .ca-nav-link:hover { color: var(--ca-orange); background: rgba(255, 90, 60, 0.07); }
.cfsa-page .ca-header-cta { display: flex; align-items: center; gap: 12px; flex: none; }

.cfsa-page .ca-burger {
  display: none; flex-direction: column; align-items: center; justify-content: center; gap: 5px;
  width: 42px; height: 42px; border: 1px solid var(--ca-line); border-radius: 10px; cursor: pointer; flex: none;
}
.cfsa-page .ca-burger span { display: block; width: 18px; height: 2px; border-radius: 2px; background: var(--ca-ink); transition: transform 0.25s ease; }
.cfsa-page .ca-nav-toggle:checked ~ .ca-header .ca-burger span:first-child { transform: translateY(3.5px) rotate(45deg); }
.cfsa-page .ca-nav-toggle:checked ~ .ca-header .ca-burger span:last-child { transform: translateY(-3.5px) rotate(-45deg); }

.cfsa-page .ca-mobile-nav {
  display: grid; grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s ease, visibility 0.3s; visibility: hidden;
  background: #FFFFFF;
}
.cfsa-page .ca-mobile-nav-inner { min-height: 0; overflow: hidden; display: flex; flex-direction: column; padding: 0 24px; }
.cfsa-page .ca-nav-toggle:checked ~ .ca-header .ca-mobile-nav { grid-template-rows: 1fr; visibility: visible; border-bottom: 1px solid var(--ca-line); box-shadow: 0 26px 40px -32px rgba(23, 23, 37, 0.35); }
.cfsa-page .ca-mobile-nav-inner a { padding: 13px 4px; border-bottom: 1px solid #F2F3F7; font-weight: 600; font-size: 0.95rem; color: #3F4152; }
.cfsa-page .ca-mobile-nav-inner a.ca-btn { margin: 16px 0 20px; border-bottom: 0; color: #FFFFFF; }

/* ==========================================================================
   HERO
   ========================================================================== */
.cfsa-page .ca-hero {
  position: relative; padding: 92px 0 120px;
  background:
    radial-gradient(1100px 700px at 8% -12%, rgba(255, 75, 53, 0.30), transparent 62%),
    radial-gradient(900px 620px at 96% 4%, rgba(255, 122, 69, 0.13), transparent 60%),
    radial-gradient(800px 800px at 55% 118%, rgba(108, 99, 255, 0.13), transparent 62%),
    #0D0D1A;
}
.cfsa-page .ca-hero::before {
  content: ""; position: absolute; inset: 0; z-index: 0; pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.045) 1px, transparent 1px);
  background-size: 44px 44px;
  -webkit-mask-image: radial-gradient(75% 60% at 50% 28%, #000 0%, transparent 100%);
          mask-image: radial-gradient(75% 60% at 50% 28%, #000 0%, transparent 100%);
}
.cfsa-page .ca-hero-inner { position: relative; z-index: 1; text-align: center; }

.cfsa-page .ca-hero-badge {
  display: inline-flex; align-items: center; gap: 10px; padding: 9px 18px; border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.16); background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.78); font-weight: 600; font-size: 0.82rem;
}
.cfsa-page .ca-hero-title {
  margin: 24px auto 0; max-width: 940px;
  font-size: clamp(2.3rem, 1.3rem + 4vw, 4.3rem);
  font-weight: 800; line-height: 1.06; letter-spacing: -0.025em; color: #FFFFFF;
  text-wrap: balance;
}
.cfsa-page .ca-ht-line { display: block; }
.cfsa-page .ca-hero-sub {
  max-width: 720px; margin: 24px auto 0; color: rgba(255, 255, 255, 0.66);
  font-size: clamp(1rem, 0.94rem + 0.3vw, 1.13rem); line-height: 1.7;
}
.cfsa-page .ca-hero-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 14px; margin-top: 36px; }

/* ---------- Hero stage & dashboard mockup ---------- */
.cfsa-page .ca-hero-stage { position: relative; max-width: 1060px; margin: 76px auto 0; perspective: 2000px; }
.cfsa-page .ca-stage-glow {
  position: absolute; inset: -8% -3%; z-index: 0; pointer-events: none;
  background: radial-gradient(58% 55% at 50% 44%, rgba(255, 90, 60, 0.20), transparent 70%);
  filter: blur(28px);
}
.cfsa-page .ca-hero-mock { position: relative; z-index: 1; transform: rotateX(9deg); transform-origin: 50% 0; }
.cfsa-page .ca-mock {
  border-radius: 18px; overflow: hidden; background: #F4F5F9; text-align: left;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 70px 120px -45px rgba(0, 0, 0, 0.8), 0 34px 90px -30px rgba(255, 90, 60, 0.32);
}
.cfsa-page .ca-mock-chrome { display: flex; align-items: center; gap: 7px; padding: 11px 14px; background: #E9EBF1; border-bottom: 1px solid #DDDFE8; }
.cfsa-page .ca-mc-dot { width: 10px; height: 10px; border-radius: 50%; background: #D7DAE3; flex: none; }
.cfsa-page .ca-mc-dot:nth-child(1) { background: #FF6B5E; }
.cfsa-page .ca-mc-dot:nth-child(2) { background: #FFC24B; }
.cfsa-page .ca-mc-dot:nth-child(3) { background: #3FCB8C; }
.cfsa-page .ca-mc-url {
  flex: 1; display: flex; align-items: center; justify-content: center; gap: 6px;
  margin: 0 10px; min-width: 0; padding: 4px 14px; border-radius: 999px;
  background: #FFFFFF; border: 1px solid #E0E2EA;
  font-size: 10px; font-weight: 600; color: #8A8FA0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.cfsa-page .ca-mc-live { display: inline-flex; align-items: center; gap: 5px; font-size: 10px; font-weight: 800; color: #16A672; flex: none; }
.cfsa-page .ca-mc-live i { width: 7px; height: 7px; border-radius: 50%; background: #2ED397; animation: caPing 2.2s ease-out infinite; }

.cfsa-page .ca-mock-body { display: flex; align-items: stretch; }

/* mock sidebar */
.cfsa-page .ca-mock-side {
  width: 176px; flex: none; background: #101022; padding: 14px 12px 16px;
  display: flex; flex-direction: column; gap: 3px; border-right: 1px solid rgba(255, 255, 255, 0.05);
}
.cfsa-page .ca-ms-brand { display: flex; align-items: center; gap: 8px; padding: 4px 8px 14px; color: #FFFFFF; font-family: var(--ca-font-head); font-weight: 700; font-size: 13px; }
.cfsa-page .ca-ms-mark { position: relative; width: 16px; height: 16px; flex: none; }
.cfsa-page .ca-ms-mark::before { content: ""; position: absolute; inset: 0; transform: rotate(45deg); border-radius: 4px; background: linear-gradient(135deg, #FF8A50, #F5372A); }
.cfsa-page .ca-ms-mark::after { content: ""; position: absolute; inset: 4.5px; transform: rotate(45deg); border-radius: 1.5px; background: #FFFFFF; }
.cfsa-page .ca-ms-label { padding: 8px 8px 6px; font-size: 8.5px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: rgba(255, 255, 255, 0.35); }
.cfsa-page .ca-ms-item {
  display: flex; align-items: center; gap: 9px; padding: 8px 9px; border-radius: 8px;
  color: rgba(255, 255, 255, 0.55); font-weight: 600; font-size: 11.5px; white-space: nowrap;
}
.cfsa-page .ca-ms-item svg { width: 14px; height: 14px; flex: none; }
.cfsa-page .ca-ms-item.active {
  background: linear-gradient(90deg, rgba(255, 90, 60, 0.18), rgba(255, 90, 60, 0.05));
  color: #FF8A6A; box-shadow: inset 3px 0 0 0 var(--ca-orange);
}
.cfsa-page .ca-ms-user { margin-top: auto; display: flex; align-items: center; gap: 9px; padding: 12px 8px 0; border-top: 1px solid rgba(255, 255, 255, 0.07); }
.cfsa-page .ca-ms-avatar { width: 26px; height: 26px; border-radius: 50%; background: linear-gradient(135deg, #FF8A50, #6C63FF); flex: none; }
.cfsa-page .ca-ms-usermeta b { display: block; color: #FFFFFF; font-size: 11px; }
.cfsa-page .ca-ms-usermeta small { display: block; color: rgba(255, 255, 255, 0.4); font-size: 9.5px; }

/* mock main */
.cfsa-page .ca-mock-main { flex: 1; min-width: 0; padding: 16px; display: flex; flex-direction: column; gap: 12px; }
.cfsa-page .ca-mm-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.cfsa-page .ca-mm-heading b { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 15px; color: var(--ca-ink); }
.cfsa-page .ca-mm-heading span { font-size: 10.5px; font-weight: 500; color: #98A0AE; }
.cfsa-page .ca-mm-tools { display: flex; align-items: center; gap: 10px; flex: none; }
.cfsa-page .ca-mm-search {
  display: flex; align-items: center; gap: 7px; width: 190px; padding: 7px 12px;
  background: #FFFFFF; border: 1px solid #E4E6EE; border-radius: 9px;
  color: #A6ACBB; font-size: 10.5px; white-space: nowrap; overflow: hidden;
}
.cfsa-page .ca-mm-bell { position: relative; width: 32px; height: 32px; border-radius: 9px; background: #FFFFFF; border: 1px solid #E4E6EE; display: flex; align-items: center; justify-content: center; color: #7A8090; }
.cfsa-page .ca-mm-bell i { position: absolute; top: 7px; right: 8px; width: 5px; height: 5px; border-radius: 50%; background: var(--ca-orange); }
.cfsa-page .ca-mm-avatar { width: 32px; height: 32px; border-radius: 50%; background: linear-gradient(135deg, #FF8A50, #F5372A); border: 2px solid #FFFFFF; box-shadow: 0 0 0 1px #E4E6EE; }

.cfsa-page .ca-mm-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.cfsa-page .ca-stat-card { background: #FFFFFF; border: 1px solid #E7E9F0; border-radius: 12px; padding: 12px 13px; min-width: 0; }
.cfsa-page .ca-stat-label { display: block; font-size: 10px; font-weight: 600; color: #98A0AE; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cfsa-page .ca-stat-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-top: 6px; }
.cfsa-page .ca-stat-row b { font-family: var(--ca-font-head); font-weight: 800; font-size: 19px; color: var(--ca-ink); letter-spacing: -0.01em; }
.cfsa-page .ca-spark { display: flex; align-items: flex-end; gap: 3px; height: 26px; margin-top: 10px; }
.cfsa-page .ca-spark i { flex: 1; min-width: 3px; max-width: 7px; border-radius: 2px 2px 0 0; background: #FFE1D8; transform-origin: bottom; animation: caBar 0.7s ease backwards; }
.cfsa-page .ca-spark i:nth-child(2) { animation-delay: 0.05s; } .cfsa-page .ca-spark i:nth-child(3) { animation-delay: 0.1s; }
.cfsa-page .ca-spark i:nth-child(4) { animation-delay: 0.15s; } .cfsa-page .ca-spark i:nth-child(5) { animation-delay: 0.2s; }
.cfsa-page .ca-spark i:nth-child(6) { animation-delay: 0.25s; } .cfsa-page .ca-spark i:nth-child(7) { animation-delay: 0.3s; }
.cfsa-page .ca-spark i:nth-child(8) { animation-delay: 0.35s; } .cfsa-page .ca-spark i:nth-child(9) { animation-delay: 0.4s; }
.cfsa-page .ca-spark i.hot { background: linear-gradient(180deg, #FF7A50, #FF5A3C); }
.cfsa-page .ca-spark i.hot-g { background: #2BC98F; }
.cfsa-page .ca-spark i.hot-p { background: #7B74FF; }
.cfsa-page .ca-csquares { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 10px; }
.cfsa-page .ca-csquares i { width: 9px; height: 9px; border-radius: 3px; background: #E8EAF1; }
.cfsa-page .ca-csquares i.on { background: #FF5A3C; }
.cfsa-page .ca-stat-note { display: block; margin-top: 8px; font-size: 9.5px; font-weight: 600; color: #98A0AE; }

.cfsa-page .ca-mm-mid { display: grid; grid-template-columns: 1.75fr 1fr; gap: 12px; }
.cfsa-page .ca-panel { background: #FFFFFF; border: 1px solid #E7E9F0; border-radius: 12px; padding: 13px 14px; min-width: 0; }
.cfsa-page .ca-card-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.cfsa-page .ca-card-head b { font-family: var(--ca-font-head); font-weight: 700; font-size: 12px; color: var(--ca-ink); white-space: nowrap; }
.cfsa-page .ca-card-sub { font-size: 9.5px; font-weight: 700; color: #16A672; white-space: nowrap; }
.cfsa-page .ca-legend { display: inline-flex; align-items: center; gap: 6px; font-size: 9.5px; font-weight: 600; color: #98A0AE; white-space: nowrap; }
.cfsa-page .ca-legend i { width: 8px; height: 8px; border-radius: 2.5px; background: #FF5A3C; }
.cfsa-page .ca-legend em { font-style: normal; width: 8px; height: 8px; border-radius: 2.5px; background: #C9CDD8; margin-left: 8px; }
.cfsa-page .ca-chart-svg { display: block; width: 100%; height: auto; }
.cfsa-page .ca-chart-svg text { font-family: var(--ca-font-body); font-size: 9px; font-weight: 600; fill: #A6ACBB; }

.cfsa-page .ca-crow { margin-bottom: 11px; }
.cfsa-page .ca-crow:last-child { margin-bottom: 0; }
.cfsa-page .ca-crow-top { display: flex; align-items: center; justify-content: space-between; font-size: 10.5px; font-weight: 600; color: #4A4E5E; }
.cfsa-page .ca-crow-top span { display: flex; align-items: center; gap: 6px; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cfsa-page .ca-crow-top span i { width: 7px; height: 7px; border-radius: 50%; flex: none; }
.cfsa-page .ca-crow-top b { font-weight: 800; color: #171725; }

.cfsa-page .ca-ord { display: grid; grid-template-columns: 1.5fr 1.1fr 1fr 0.7fr 1fr; gap: 8px; align-items: center; padding: 8px 2px; border-top: 1px solid #F0F1F6; font-size: 10.5px; font-weight: 600; color: #4A4E5E; }
.cfsa-page .ca-ord-head { border-top: 0; border-bottom: 1px solid #F0F1F6; padding: 0 2px 8px; font-size: 8.5px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: #A0A6B4; }
.cfsa-page .ca-ord span { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cfsa-page .ca-ord-r { text-align: right; }
.cfsa-page .ca-ord-user { display: flex; align-items: center; gap: 8px; }
.cfsa-page .ca-ord-user i {
  display: flex; align-items: center; justify-content: center; flex: none;
  width: 22px; height: 22px; border-radius: 50%; font-style: normal; font-size: 8.5px; font-weight: 800;
}
.cfsa-page .ca-pri-h { color: #E04B2F; font-weight: 800; }

/* floating chips */
.cfsa-page .ca-float-chip {
  position: absolute; z-index: 3; display: flex; align-items: center; gap: 12px;
  background: rgba(255, 255, 255, 0.96); border: 1px solid rgba(23, 23, 37, 0.06);
  border-radius: 14px; padding: 12px 16px; text-align: left;
  box-shadow: 0 24px 50px -20px rgba(13, 13, 26, 0.45);
  animation: caFloat 6s ease-in-out infinite;
}
.cfsa-page .ca-chip-a { top: 9%; right: -10px; }
.cfsa-page .ca-chip-b { left: -12px; bottom: 15%; animation-delay: -3s; }
.cfsa-page .ca-chip-txt b { display: block; font-family: var(--ca-font-head); font-weight: 800; font-size: 1rem; color: var(--ca-ink); line-height: 1.15; }
.cfsa-page .ca-chip-txt small { display: block; margin-top: 2px; font-size: 11px; font-weight: 600; color: #8A90A0; }
.cfsa-page .ca-chip-ico {
  flex: none; width: 38px; height: 38px; border-radius: 11px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255, 90, 60, 0.12); color: #FF5A3C;
}
.cfsa-page .ca-hero-shadow {
  position: absolute; bottom: -14px; left: 14%; right: 14%; height: 34px; z-index: 0;
  background: radial-gradient(50% 100% at 50% 0%, rgba(255, 90, 60, 0.32), transparent 75%);
  filter: blur(10px);
}

/* ==========================================================================
   TRUST / KPIs
   ========================================================================== */
.cfsa-page .ca-trust { background: #FFFFFF; padding: 72px 0 64px; border-bottom: 1px solid #F0F1F5; }
.cfsa-page .ca-trust-label {
  display: flex; align-items: center; justify-content: center; gap: 20px;
  font-weight: 700; font-size: 0.74rem; letter-spacing: 0.2em; text-transform: uppercase; color: #9AA1AD;
}
.cfsa-page .ca-trust-label::before,
.cfsa-page .ca-trust-label::after { content: ""; flex: none; width: 64px; height: 1px; background: #E7E9F0; }
.cfsa-page .ca-stats { display: flex; justify-content: center; margin-top: 44px; }
.cfsa-page .ca-stat { flex: 1; max-width: 300px; text-align: center; padding: 6px 18px; }
.cfsa-page .ca-stat + .ca-stat { border-left: 1px solid #E9EBF2; }
.cfsa-page .ca-stat-num {
  display: block; font-family: var(--ca-font-head); font-weight: 800;
  font-size: clamp(2.1rem, 1.6rem + 2vw, 3rem); line-height: 1;
  letter-spacing: -0.03em; color: var(--ca-ink);
}
.cfsa-page .ca-stat-num .ca-unit { font-size: 0.62em; font-weight: 800; margin-left: 2px; }
.cfsa-page .ca-stat-num .ca-plus { color: var(--ca-orange); }
.cfsa-page .ca-stat-cap {
  display: block; margin-top: 10px; font-weight: 600; font-size: 0.8rem;
  letter-spacing: 0.06em; text-transform: uppercase; color: #8A90A0;
}
.cfsa-page .ca-partners {
  display: flex; flex-wrap: wrap; justify-content: center; align-items: center;
  gap: 22px 64px; margin-top: 52px; padding-top: 36px; border-top: 1px solid #F0F1F5;
}
.cfsa-page .ca-partners-label {
  flex-basis: 100%; text-align: center; font-size: 0.72rem; font-weight: 700;
  letter-spacing: 0.18em; text-transform: uppercase; color: #B3B8C4;
}
.cfsa-page .ca-partner { color: #A7ACB8; display: inline-flex; align-items: center; gap: 9px; cursor: default; transition: color 0.25s ease; }
.cfsa-page .ca-partner:hover { color: #5D6270; }
.cfsa-page .ca-p-snow { font-family: var(--ca-font-head); font-weight: 800; font-size: 1.25rem; letter-spacing: -0.02em; }
.cfsa-page .ca-diamond-sm { width: 11px; height: 11px; transform: rotate(45deg); background: currentColor; border-radius: 3px; opacity: 0.85; }
.cfsa-page .ca-p-flow { font-weight: 600; font-size: 0.95rem; letter-spacing: 0.28em; }
.cfsa-page .ca-p-va { font-family: Georgia, 'Times New Roman', serif; font-style: italic; font-weight: 700; font-size: 1.2rem; }
.cfsa-page .ca-p-ai { font-size: 1rem; letter-spacing: -0.01em; }
.cfsa-page .ca-p-ai b { font-weight: 800; }

/* ==========================================================================
   PROBLEM
   ========================================================================== */
.cfsa-page .ca-problem { background: #FFFFFF; }
.cfsa-page .ca-cards3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
.cfsa-page .ca-pcard {
  position: relative; overflow: hidden; background: #FCFCFE;
  border: 1px solid var(--ca-line); border-radius: 18px; padding: 30px 28px 26px;
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.cfsa-page .ca-pcard::before {
  content: ""; position: absolute; top: 0; left: 28px; width: 44px; height: 3px;
  border-radius: 0 0 3px 3px; background: var(--acc);
}
.cfsa-page .ca-pcard .ca-ico-tile { margin-bottom: 18px; }
.cfsa-page .ca-pcard h3 { font-weight: 700; font-size: 1.15rem; color: var(--ca-ink); margin-bottom: 14px; }
.cfsa-page .ca-pcard li { position: relative; padding-left: 18px; margin-top: 10px; color: var(--ca-gray); font-size: 0.92rem; line-height: 1.55; }
.cfsa-page .ca-pcard li::before { content: ""; position: absolute; left: 0; top: 0.6em; width: 8px; height: 2px; border-radius: 2px; background: var(--acc); }
.cfsa-page .ca-pcard:hover { transform: translateY(-5px); border-color: var(--acc-line); box-shadow: var(--ca-shadow); }

/* ==========================================================================
   ADVANTAGE / PLATFORM HUB
   ========================================================================== */
.cfsa-page .ca-advantage {
  background:
    radial-gradient(900px 640px at 50% 40%, rgba(255, 75, 53, 0.13), transparent 65%),
    radial-gradient(700px 500px at 10% 100%, rgba(108, 99, 255, 0.10), transparent 60%),
    #0B0B17;
}
.cfsa-page .ca-adv-grid {
  --ca-conn: 64px;
  display: grid; grid-template-columns: minmax(0, 1fr) 340px minmax(0, 1fr);
  grid-template-areas: "left center right";
  column-gap: var(--ca-conn); align-items: center; row-gap: 40px;
}
.cfsa-page .ca-adv-left { grid-area: left; }
.cfsa-page .ca-adv-right { grid-area: right; }
.cfsa-page .ca-adv-center { grid-area: center; }

.cfsa-page .ca-adv-col { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.cfsa-page .ca-adv-left { align-items: flex-end; }
.cfsa-page .ca-adv-right { align-items: flex-start; }
.cfsa-page .ca-adv-item {
  position: relative; width: min(100%, 350px);
  display: flex; align-items: center; gap: 13px;
  background: linear-gradient(180deg, #191932, #141428);
  border: 1px solid rgba(255, 255, 255, 0.09); border-radius: 14px; padding: 14px 16px;
  box-shadow: 0 14px 30px -18px rgba(0, 0, 0, 0.7);
  transition: transform 0.3s ease, border-color 0.3s ease;
}
.cfsa-page .ca-adv-item:hover { transform: translateY(-3px); border-color: rgba(255, 106, 61, 0.45); }
.cfsa-page .ca-adv-ico {
  flex: none; width: 38px; height: 38px; border-radius: 11px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255, 90, 60, 0.12); color: #FF8A6A;
}
.cfsa-page .ca-adv-col .ca-adv-item:nth-child(even) .ca-adv-ico { background: rgba(108, 99, 255, 0.14); color: #9B94FF; }
.cfsa-page .ca-adv-txt b { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 0.95rem; color: #FFFFFF; }
.cfsa-page .ca-adv-txt small { display: block; margin-top: 3px; color: rgba(255, 255, 255, 0.5); font-size: 0.8rem; }

/* connectors */
.cfsa-page .ca-adv-item::before,
.cfsa-page .ca-adv-item::after { content: ""; position: absolute; top: 50%; transform: translateY(-50%); }
.cfsa-page .ca-adv-left .ca-adv-item::after { right: calc(-1 * var(--ca-conn)); width: var(--ca-conn); height: 1px; background: linear-gradient(90deg, rgba(255, 106, 61, 0.55), rgba(255, 106, 61, 0)); }
.cfsa-page .ca-adv-left .ca-adv-item::before { right: calc(-1 * var(--ca-conn) - 10px); width: 7px; height: 7px; border-radius: 50%; background: #FF6A3D; box-shadow: 0 0 10px rgba(255, 106, 61, 0.8); }
.cfsa-page .ca-adv-right .ca-adv-item::after { left: calc(-1 * var(--ca-conn)); width: var(--ca-conn); height: 1px; background: linear-gradient(270deg, rgba(255, 106, 61, 0.55), rgba(255, 106, 61, 0)); }
.cfsa-page .ca-adv-right .ca-adv-item::before { left: calc(-1 * var(--ca-conn) - 10px); width: 7px; height: 7px; border-radius: 50%; background: #FF6A3D; box-shadow: 0 0 10px rgba(255, 106, 61, 0.8); }

/* hub */
.cfsa-page .ca-adv-center { position: relative; height: 480px; display: flex; align-items: center; justify-content: center; }
.cfsa-page .ca-orbit {
  position: absolute; top: 50%; left: 50%; width: 408px; height: 408px; margin: -204px 0 0 -204px;
  border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 50%;
  animation: caSpin 28s linear infinite;
}
.cfsa-page .ca-orbit-dot {
  position: absolute; top: -4.5px; left: 50%; width: 9px; height: 9px; margin-left: -4.5px;
  border-radius: 50%; background: #FF6A3D; box-shadow: 0 0 14px rgba(255, 90, 45, 0.9);
}
.cfsa-page .ca-ring-dashed {
  position: absolute; top: 50%; left: 50%; width: 310px; height: 310px; margin: -155px 0 0 -155px;
  border: 1px dashed rgba(255, 255, 255, 0.16); border-radius: 50%;
  animation: caSpinRev 70s linear infinite;
}
.cfsa-page .ca-adv-logo {
  position: relative; width: 200px; height: 200px; border-radius: 50%;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 7px;
  background: radial-gradient(circle at 35% 28%, #23233F, #101020 72%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 0 0 10px rgba(255, 255, 255, 0.02), 0 0 90px rgba(255, 90, 60, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.cfsa-page .ca-adv-word { font-family: var(--ca-font-head); font-weight: 800; font-size: 1.35rem; color: #FFFFFF; letter-spacing: -0.03em; }
.cfsa-page .ca-adv-sub { font-size: 9px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; color: rgba(255, 255, 255, 0.45); }

/* ==========================================================================
   CORE WORKFLOWS
   ========================================================================== */
.cfsa-page .ca-workflows {
  background:
    radial-gradient(900px 600px at 92% 0%, rgba(108, 99, 255, 0.10), transparent 60%),
    radial-gradient(800px 520px at 4% 100%, rgba(255, 75, 53, 0.08), transparent 60%),
    #0D0D1A;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.cfsa-page .ca-wf-layout { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 28px; align-items: start; }

.cfsa-page .ca-wf-tabs { display: flex; flex-direction: column; gap: 10px; position: sticky; top: 96px; }
.cfsa-page .ca-wf-tab {
  display: flex; align-items: center; gap: 13px; padding: 15px 16px; border-radius: 14px;
  border: 1px solid transparent; color: rgba(255, 255, 255, 0.62);
  transition: background 0.25s ease, color 0.25s ease, border-color 0.25s ease;
}
.cfsa-page .ca-wf-tab:hover { background: rgba(255, 255, 255, 0.04); color: #FFFFFF; }
.cfsa-page .ca-wf-tab-ico {
  flex: none; width: 38px; height: 38px; border-radius: 11px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255, 255, 255, 0.06); color: rgba(255, 255, 255, 0.7);
}
.cfsa-page .ca-wf-tab-txt { min-width: 0; }
.cfsa-page .ca-wf-tab-txt b { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 0.93rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cfsa-page .ca-wf-tab-txt small { display: block; margin-top: 2px; font-size: 0.78rem; color: rgba(255, 255, 255, 0.4); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cfsa-page .ca-wf-chev { margin-left: auto; flex: none; width: 8px; height: 8px; border-top: 2px solid currentColor; border-right: 2px solid currentColor; transform: rotate(45deg); opacity: 0.5; }
.cfsa-page .ca-wf-tab.active {
  background: linear-gradient(135deg, rgba(255, 90, 60, 0.16), rgba(255, 90, 60, 0.05));
  border-color: rgba(255, 90, 60, 0.35); color: #FFFFFF;
  box-shadow: inset 3px 0 0 0 var(--ca-orange);
}
.cfsa-page .ca-wf-tab.active .ca-wf-tab-ico { background: rgba(255, 90, 60, 0.18); color: #FF8A6A; }

.cfsa-page .ca-showcase {
  background: linear-gradient(180deg, #181834, #12122A);
  border: 1px solid rgba(255, 255, 255, 0.09); border-radius: 22px;
  padding: 26px 26px 42px; box-shadow: 0 40px 80px -40px rgba(0, 0, 0, 0.6);
}
.cfsa-page .ca-wf-stage { position: relative; background: #EEF0F5; border-radius: 16px; padding: 22px 22px 30px; }

.cfsa-page .ca-board {
  background: #FFFFFF; border: 1px solid #E4E6EE; border-radius: 14px; overflow: hidden;
  box-shadow: 0 20px 40px -20px rgba(23, 23, 37, 0.28);
}
.cfsa-page .ca-sb-chrome { display: flex; align-items: center; gap: 6px; padding: 9px 12px; background: #EDEFF4; border-bottom: 1px solid #E2E4EC; }
.cfsa-page .ca-sb-chrome i { width: 9px; height: 9px; border-radius: 50%; background: #D7DAE3; }
.cfsa-page .ca-sb-chrome i:nth-child(1) { background: #FF6B5E; }
.cfsa-page .ca-sb-chrome i:nth-child(2) { background: #FFC24B; }
.cfsa-page .ca-sb-chrome i:nth-child(3) { background: #3FCB8C; }
.cfsa-page .ca-sb-chrome span { margin-left: 8px; font-size: 10px; font-weight: 600; color: #98A0AE; }
.cfsa-page .ca-sb-body { display: flex; align-items: stretch; }
.cfsa-page .ca-sb-side {
  width: 52px; flex: none; background: #101022; padding: 10px 0;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
}
.cfsa-page .ca-sb-logo { position: relative; width: 18px; height: 18px; margin-bottom: 6px; }
.cfsa-page .ca-sb-logo::before { content: ""; position: absolute; inset: 0; transform: rotate(45deg); border-radius: 4px; background: linear-gradient(135deg, #FF8A50, #F5372A); }
.cfsa-page .ca-sb-logo::after { content: ""; position: absolute; inset: 5px; transform: rotate(45deg); border-radius: 1.5px; background: #FFFFFF; }
.cfsa-page .ca-sb-side span {
  width: 30px; height: 30px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255, 255, 255, 0.5); background: rgba(255, 255, 255, 0.05);
}
.cfsa-page .ca-sb-side span.active { color: #FF8A6A; background: rgba(255, 90, 60, 0.16); }
.cfsa-page .ca-sb-main { flex: 1; min-width: 0; padding: 14px; }
.cfsa-page .ca-sb-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.cfsa-page .ca-sb-title b { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 13px; color: var(--ca-ink); }
.cfsa-page .ca-sb-title span { display: flex; align-items: center; gap: 6px; margin-top: 3px; font-size: 9.5px; font-weight: 700; color: #E04B2F; }
.cfsa-page .ca-sb-chip { flex: none; font-size: 9.5px; font-weight: 700; color: #5D6270; background: #F1F2F7; border-radius: 999px; padding: 4px 10px; }
.cfsa-page .ca-sb-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 12px; }
.cfsa-page .ca-sb-stats div { background: #F7F8FB; border: 1px solid #ECEEF4; border-radius: 10px; padding: 9px 11px; min-width: 0; }
.cfsa-page .ca-sb-stats span { display: block; font-size: 9px; font-weight: 600; color: #98A0AE; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cfsa-page .ca-sb-stats b { display: block; margin-top: 3px; font-family: var(--ca-font-head); font-weight: 800; font-size: 15px; color: var(--ca-ink); }
.cfsa-page .ca-sb-lower { display: grid; grid-template-columns: auto 1fr; gap: 16px; margin-top: 12px; align-items: center; }
.cfsa-page .ca-sb-donut { position: relative; width: 110px; height: 110px; }
.cfsa-page .ca-donut-txt { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.cfsa-page .ca-donut-txt b { font-family: var(--ca-font-head); font-weight: 800; font-size: 20px; color: var(--ca-ink); }
.cfsa-page .ca-donut-txt span { font-size: 8.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #98A0AE; }
.cfsa-page .ca-sb-rows { min-width: 0; }

/* phone + Virtual Agent chat mockup */
.cfsa-page .ca-phone {
  position: absolute; right: 30px; bottom: -26px; z-index: 2; width: 176px;
  border: 7px solid #17172F; border-radius: 30px; background: #FFFFFF;
  box-shadow: 0 30px 60px -18px rgba(13, 13, 26, 0.55), 0 0 0 1px rgba(255, 255, 255, 0.08);
}
.cfsa-page .ca-phone-screen {
  position: relative; overflow: hidden; border-radius: 22px; background: #F7F8FB;
  padding: 34px 12px 12px; min-height: 330px;
  display: flex; flex-direction: column; gap: 10px;
}
.cfsa-page .ca-phone-notch { position: absolute; top: 8px; left: 50%; transform: translateX(-50%); width: 64px; height: 13px; border-radius: 999px; background: #17172F; }

.cfsa-page .ca-va-head { display: flex; align-items: center; gap: 10px; }
.cfsa-page .ca-va-ava {
  flex: none; width: 30px; height: 30px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, #FF8A50, #F5372A); color: #FFFFFF;
  font-size: 10px; font-weight: 800;
}
.cfsa-page .ca-va-hmeta b { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 12.5px; color: var(--ca-ink); }
.cfsa-page .ca-va-hmeta small { display: flex; align-items: center; gap: 4px; margin-top: 1px; font-size: 9px; font-weight: 700; color: #16A672; }
.cfsa-page .ca-va-chat { display: flex; flex-direction: column; gap: 8px; }
.cfsa-page .ca-va-msg { max-width: 88%; padding: 8px 10px; border-radius: 12px; font-size: 10px; line-height: 1.5; }
.cfsa-page .ca-va-bot {
  align-self: flex-start; background: #FFFFFF; border: 1px solid #ECEEF4;
  border-bottom-left-radius: 4px; color: #454A5A;
  box-shadow: 0 8px 16px -10px rgba(23, 23, 37, 0.18);
}
.cfsa-page .ca-va-bot b { color: #E04B2F; font-weight: 800; }
.cfsa-page .ca-va-name { display: block; font-size: 8px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: #FF8A6A; margin-bottom: 3px; }
.cfsa-page .ca-va-student {
  align-self: flex-end; color: #FFFFFF; font-weight: 600;
  background: linear-gradient(135deg, #FF6A3D, #F5372A);
  border-bottom-right-radius: 4px; box-shadow: 0 8px 16px -8px rgba(245, 55, 42, 0.45);
}
.cfsa-page .ca-va-input {
  margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: 8px;
  background: #FFFFFF; border: 1px solid #ECEEF4; border-radius: 12px;
  padding: 9px 10px; font-size: 9.5px; color: #A6ACBB;
}
.cfsa-page .ca-va-send {
  flex: none; width: 24px; height: 24px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, #FF6A3D, #F5372A); color: #FFFFFF;
}

.cfsa-page .ca-wf-content { display: grid; grid-template-columns: 1.15fr 1fr; gap: 26px; margin-top: 28px; align-items: start; }
.cfsa-page .ca-wf-tag {
  display: inline-flex; padding: 6px 12px; border-radius: 999px;
  font-size: 10px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase;
  color: #FF8A6A; background: rgba(255, 90, 60, 0.12); border: 1px solid rgba(255, 90, 60, 0.3);
}
.cfsa-page .ca-wf-copy h3 { margin-top: 14px; font-weight: 800; font-size: 1.6rem; color: #FFFFFF; letter-spacing: -0.02em; }
.cfsa-page .ca-wf-copy p { margin-top: 12px; color: rgba(255, 255, 255, 0.6); line-height: 1.7; font-size: 0.95rem; }
.cfsa-page .ca-wf-actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 28px; }

/* ==========================================================================
   12 USE CASES
   ========================================================================== */
.cfsa-page .ca-uc { background: #FFFFFF; }
.cfsa-page .ca-uc-tabs { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 42px; }
.cfsa-page .ca-uc-tab {
  padding: 11px 20px; border-radius: 999px; border: 1px solid var(--ca-line); background: #FFFFFF;
  color: #4A4E5E; font-family: var(--ca-font-body); font-weight: 600; font-size: 0.88rem; cursor: pointer;
  transition: border-color 0.25s ease, color 0.25s ease, background 0.25s ease, box-shadow 0.25s ease;
}
.cfsa-page .ca-uc-tab:hover { border-color: #FFB09E; color: var(--ca-orange); }
.cfsa-page .ca-uc-tab.active { background: var(--ca-ink); border-color: var(--ca-ink); color: #FFFFFF; box-shadow: 0 10px 24px -10px rgba(23, 23, 37, 0.45); }

.cfsa-page .ca-uc-card {
  display: grid; grid-template-columns: 0.9fr 1.1fr; gap: 44px;
  background: var(--ca-bg-soft); border: 1px solid #ECEDF2; border-radius: 24px;
  padding: 44px; box-shadow: 0 30px 70px -50px rgba(23, 23, 37, 0.35);
}
.cfsa-page .ca-uc-tag {
  display: inline-flex; padding: 6px 12px; border-radius: 999px;
  font-size: 10px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--ca-orange); background: rgba(255, 90, 60, 0.08); border: 1px solid rgba(255, 90, 60, 0.25);
}
.cfsa-page .ca-uc-info h3 { margin-top: 16px; font-weight: 800; font-size: clamp(1.5rem, 1.2rem + 1vw, 2rem); line-height: 1.2; letter-spacing: -0.02em; color: var(--ca-ink); }
.cfsa-page .ca-uc-info p { margin-top: 14px; color: var(--ca-gray); line-height: 1.7; font-size: 0.96rem; }
.cfsa-page .ca-uc-info .ca-check-list { margin-top: 22px; }
.cfsa-page .ca-uc-info .ca-btn { margin-top: 28px; }

.cfsa-page .ca-uc-visual {
  position: relative; border-radius: 16px; overflow: hidden;
  border: 1px solid #E4E1DA; background: #F3EBDD; min-height: 340px; align-self: stretch;
  display: flex;
}
.cfsa-page .ca-uc-scene { display: block; width: 100%; height: 100%; }
.cfsa-page .ca-uc-chip {
  position: absolute; display: flex; align-items: center; gap: 11px;
  background: rgba(255, 255, 255, 0.95); border-radius: 14px; padding: 12px 14px;
  box-shadow: 0 18px 36px -16px rgba(23, 23, 37, 0.35); text-align: left;
}
.cfsa-page .ca-uc-chip-a { top: 14px; right: 14px; }
.cfsa-page .ca-uc-chip-b { bottom: 14px; left: 14px; }
.cfsa-page .ca-uc-chip b { font-family: var(--ca-font-head); font-weight: 800; font-size: 1.1rem; color: var(--ca-ink); }
.cfsa-page .ca-uc-chip-txt small { display: block; font-size: 9.5px; font-weight: 700; color: #98A0AE; text-transform: uppercase; letter-spacing: 0.06em; }
.cfsa-page .ca-uc-chip-b b { display: block; margin-top: 3px; font-family: var(--ca-font-head); font-weight: 700; font-size: 11.5px; color: var(--ca-ink); }

/* ==========================================================================
   PROCESS / TIMELINE
   ========================================================================== */
.cfsa-page .ca-how { background: #FFFFFF; }
.cfsa-page .ca-how-steps { position: relative; max-width: 980px; margin: 0 auto; }
.cfsa-page .ca-how-steps::before {
  content: ""; position: absolute; left: 23px; top: 30px; bottom: 30px; width: 2px; border-radius: 2px;
  background: linear-gradient(180deg, #FF5A3C 0%, rgba(255, 90, 60, 0.35) 45%, rgba(108, 99, 255, 0.35) 100%);
}
.cfsa-page .ca-how-step { position: relative; display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 14px 44px; padding-bottom: 26px; }
.cfsa-page .ca-how-step:last-child { padding-bottom: 0; }
.cfsa-page .ca-how-rail { display: flex; align-items: center; gap: 15px; padding-top: 20px; }
.cfsa-page .ca-how-num {
  flex: none; width: 48px; height: 48px; border-radius: 50%; position: relative; z-index: 1;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--ca-font-head); font-weight: 800; font-size: 1rem;
  background: #FFFFFF; border: 2px solid #E3E5EC; color: #8A90A0;
}
.cfsa-page .ca-how-step:first-child .ca-how-num {
  background: linear-gradient(135deg, #FF6A3D, #F5372A); border-color: transparent; color: #FFFFFF;
  box-shadow: 0 10px 22px -8px rgba(245, 55, 42, 0.55);
}
.cfsa-page .ca-how-meta { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 0.95rem; line-height: 1.3; color: var(--ca-ink); }
.cfsa-page .ca-how-meta small { display: block; font-family: var(--ca-font-body); font-size: 0.68rem; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: #A0A6B4; margin-bottom: 3px; }
.cfsa-page .ca-how-card {
  position: relative; overflow: hidden; display: flex; align-items: flex-start; gap: 16px;
  background: #FFFFFF; border: 1px solid var(--ca-line); border-radius: 16px; padding: 22px 24px;
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.cfsa-page .ca-how-card::after {
  content: attr(data-step); position: absolute; right: 16px; top: 2px;
  font-family: var(--ca-font-head); font-weight: 800; font-size: 44px; line-height: 1;
  color: #F1F2F7; letter-spacing: -0.02em;
}
.cfsa-page .ca-how-card:hover { transform: translateY(-3px); border-color: var(--acc-line); box-shadow: var(--ca-shadow); }
.cfsa-page .ca-how-txt h3 { font-weight: 700; font-size: 1.05rem; color: var(--ca-ink); }
.cfsa-page .ca-how-txt p { margin-top: 7px; color: var(--ca-gray); font-size: 0.92rem; line-height: 1.65; padding-right: 34px; }

/* ==========================================================================
   PLATFORM / IMPACT
   ========================================================================== */
.cfsa-page .ca-infra { background: var(--ca-bg-soft); border-top: 1px solid #EDEEF3; }
.cfsa-page .ca-cards4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.cfsa-page .ca-icard {
  position: relative; overflow: hidden; background: #FFFFFF;
  border: 1px solid var(--ca-line); border-radius: 18px; padding: 26px 24px;
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.cfsa-page .ca-icard::before {
  content: ""; position: absolute; top: 0; left: 24px; width: 38px; height: 3px;
  border-radius: 0 0 3px 3px; background: var(--acc);
}
.cfsa-page .ca-icard:hover { transform: translateY(-4px); border-color: var(--acc-line); box-shadow: var(--ca-shadow); }
.cfsa-page .ca-icard h3 { margin: 16px 0 10px; font-weight: 700; font-size: 1.05rem; color: var(--ca-ink); }
.cfsa-page .ca-icard p { color: var(--ca-gray); font-size: 0.9rem; line-height: 1.65; }

/* build roadmap / phases */
.cfsa-page .ca-phases { margin-top: 56px; padding-top: 42px; border-top: 1px dashed #E1E3EB; }
.cfsa-page .ca-phases-head { text-align: center; margin-bottom: 26px; }
.cfsa-page .ca-phases-head span { display: block; font-size: 0.72rem; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: var(--ca-orange); }
.cfsa-page .ca-phases-head p { margin-top: 6px; font-family: var(--ca-font-head); font-weight: 700; font-size: 1.05rem; color: var(--ca-ink); }
.cfsa-page .ca-phase-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; }
.cfsa-page .ca-phase {
  display: inline-flex; align-items: center; gap: 9px; padding: 9px 14px 9px 9px;
  border: 1px solid var(--ca-line); background: #FFFFFF; border-radius: 999px;
  font-size: 0.8rem; font-weight: 700; color: #454A5A;
}
.cfsa-page .ca-phase-num {
  width: 24px; height: 24px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255, 90, 60, 0.12); color: #E04B2F;
  font-family: var(--ca-font-head); font-size: 0.72rem; font-weight: 800;
}

/* ==========================================================================
   TEAM
   ========================================================================== */
.cfsa-page .ca-team { background: #FFFFFF; }
.cfsa-page .ca-member {
  position: relative; overflow: hidden; background: #FFFFFF;
  border: 1px solid var(--ca-line); border-radius: 18px; padding: 26px 24px;
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.cfsa-page .ca-member::before {
  content: ""; position: absolute; top: 0; left: 24px; width: 38px; height: 3px;
  border-radius: 0 0 3px 3px; background: var(--acc);
}
.cfsa-page .ca-member:hover { transform: translateY(-4px); border-color: var(--acc-line); box-shadow: var(--ca-shadow); }
.cfsa-page .ca-avatar {
  width: 54px; height: 54px; border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  background: var(--acc); color: #FFFFFF;
  font-family: var(--ca-font-head); font-weight: 800; font-size: 1.05rem;
  box-shadow: 0 12px 24px -12px rgba(23, 23, 37, 0.35);
}
.cfsa-page .ca-member h3 { margin-top: 16px; font-weight: 700; font-size: 1.05rem; color: var(--ca-ink); }
.cfsa-page .ca-member-role { display: block; margin-top: 5px; font-size: 0.78rem; font-weight: 800; color: var(--acc); }
.cfsa-page .ca-member p { margin-top: 10px; color: var(--ca-gray); font-size: 0.9rem; line-height: 1.65; }

/* ==========================================================================
   CTA + FOOTER
   ========================================================================== */
.cfsa-page .ca-cta {
  position: relative; text-align: center; padding: 110px 0 120px;
  background:
    radial-gradient(820px 430px at 50% -10%, rgba(255, 90, 60, 0.26), transparent 65%),
    radial-gradient(620px 300px at 50% 115%, rgba(108, 99, 255, 0.12), transparent 60%),
    #0C0C18;
}
.cfsa-page .ca-cta-title {
  max-width: 760px; margin: 0 auto; font-weight: 800;
  font-size: clamp(1.9rem, 1.3rem + 2.4vw, 3rem); line-height: 1.15;
  letter-spacing: -0.02em; color: #FFFFFF;
}
.cfsa-page .ca-cta p { max-width: 560px; margin: 18px auto 0; color: rgba(255, 255, 255, 0.6); line-height: 1.7; }
.cfsa-page .ca-cta-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 14px; margin-top: 34px; }
.cfsa-page .ca-cta-meta { display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 14px; margin-top: 36px; color: rgba(255, 255, 255, 0.45); font-size: 0.85rem; font-weight: 600; }
.cfsa-page .ca-cta-meta i { width: 4px; height: 4px; border-radius: 50%; background: rgba(255, 255, 255, 0.25); }

.cfsa-page .ca-footer { background: #0A0A13; border-top: 1px solid rgba(255, 255, 255, 0.06); padding-top: 64px; color: rgba(255, 255, 255, 0.55); }
.cfsa-page .ca-footer-top { display: grid; grid-template-columns: 1.6fr 1fr 1fr 1fr; gap: 40px; padding-bottom: 48px; }
.cfsa-page .ca-footer-brand p { margin-top: 14px; font-size: 0.9rem; line-height: 1.65; max-width: 280px; color: rgba(255, 255, 255, 0.45); }
.cfsa-page .ca-footer-col b { display: block; font-family: var(--ca-font-head); font-weight: 700; font-size: 0.8rem; letter-spacing: 0.12em; text-transform: uppercase; color: #FFFFFF; margin-bottom: 16px; }
.cfsa-page .ca-footer-col a { display: block; padding: 6px 0; color: rgba(255, 255, 255, 0.5); font-size: 0.9rem; transition: color 0.2s ease; }
.cfsa-page .ca-footer-col a:hover { color: #FF8A6A; }
.cfsa-page .ca-footer-bar {
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.07); padding: 22px 0;
  font-size: 0.82rem; color: rgba(255, 255, 255, 0.38);
}
.cfsa-page .ca-footer-legal { display: flex; gap: 22px; }
.cfsa-page .ca-footer-legal a { color: rgba(255, 255, 255, 0.38); transition: color 0.2s ease; }
.cfsa-page .ca-footer-legal a:hover { color: #FF8A6A; }

/* ==========================================================================
   KEYFRAMES (prefixed to avoid portal collisions)
   ========================================================================== */
@keyframes caPing {
  0% { box-shadow: 0 0 0 0 rgba(46, 211, 151, 0.55); }
  70% { box-shadow: 0 0 0 7px rgba(46, 211, 151, 0); }
  100% { box-shadow: 0 0 0 0 rgba(46, 211, 151, 0); }
}
@keyframes caFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-9px); }
}
@keyframes caSpin { to { transform: rotate(360deg); } }
@keyframes caSpinRev { to { transform: rotate(-360deg); } }
@keyframes caBar { from { transform: scaleY(0); } }

/* ==========================================================================
   RESPONSIVE
   ========================================================================== */

/* ----- header ----- */
@media (max-width: 980px) {
  .cfsa-page .ca-nav-links { display: none; }
  .cfsa-page .ca-burger { display: inline-flex; }
}
@media (max-width: 600px) {
  .cfsa-page .ca-header-cta .ca-btn { display: none; }
  .cfsa-page .ca-header-inner { height: 64px; }
}

/* ----- hero ----- */
@media (max-width: 900px) {
  .cfsa-page .ca-hero { padding: 76px 0 96px; }
  .cfsa-page .ca-hero-mock { transform: rotateX(4deg); }
  .cfsa-page .ca-hero-stage { margin-top: 60px; }
}
@media (max-width: 820px) {
  .cfsa-page .ca-mm-stats { grid-template-columns: repeat(2, 1fr); }
  .cfsa-page .ca-mm-mid { grid-template-columns: 1fr; }
}
@media (max-width: 780px) {
  .cfsa-page .ca-mock-side { display: none; }
}
@media (max-width: 760px) {
  .cfsa-page .ca-ord { grid-template-columns: 1.4fr 1fr 0.7fr 1fr; }
  .cfsa-page .ca-ord-cat { display: none; }
}
@media (max-width: 680px) {
  .cfsa-page .ca-mm-search { width: 130px; }
}
@media (max-width: 640px) {
  .cfsa-page .ca-chip-b { display: none; }
  .cfsa-page .ca-chip-a { top: -18px; right: 6px; padding: 10px 13px; }
  .cfsa-page .ca-chip-txt b { font-size: 0.9rem; }
  .cfsa-page .ca-chip-txt small { font-size: 10px; }
}
@media (max-width: 520px) {
  .cfsa-page .ca-hero-actions { flex-direction: column; align-items: stretch; }
  .cfsa-page .ca-hero-actions .ca-btn { width: 100%; }
  .cfsa-page .ca-ord { grid-template-columns: 1.3fr 0.7fr 1fr; }
  .cfsa-page .ca-ord-hall { display: none; }
  .cfsa-page .ca-mm-search { display: none; }
}

/* ----- trust ----- */
@media (max-width: 640px) {
  .cfsa-page .ca-trust-label { flex-direction: column; gap: 12px; text-align: center; }
  .cfsa-page .ca-trust-label::before, .cfsa-page .ca-trust-label::after { display: none; }
  .cfsa-page .ca-stats { flex-direction: column; margin-top: 36px; }
  .cfsa-page .ca-stat { max-width: none; padding: 6px 0; }
  .cfsa-page .ca-stat + .ca-stat { border-left: 0; border-top: 1px solid #E9EBF2; margin-top: 22px; padding-top: 22px; }
  .cfsa-page .ca-partners { gap: 18px 34px; margin-top: 40px; padding-top: 32px; }
}

/* ----- sections / problem ----- */
@media (max-width: 900px) {
  .cfsa-page .ca-cards3 { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .cfsa-page .ca-sec { padding: 64px 0; }
  .cfsa-page .ca-sec-head { margin-bottom: 40px; }
}

/* ----- advantage ----- */
@media (max-width: 1150px) {
  .cfsa-page .ca-adv-grid { --ca-conn: 44px; }
}
@media (max-width: 940px) {
  .cfsa-page .ca-adv-grid { grid-template-columns: 1fr 1fr; grid-template-areas: "center center" "left right"; row-gap: 44px; }
  .cfsa-page .ca-adv-item::before, .cfsa-page .ca-adv-item::after { display: none; }
  .cfsa-page .ca-adv-col { align-items: stretch; }
  .cfsa-page .ca-adv-item { width: 100%; }
  .cfsa-page .ca-adv-center { height: 420px; }
  .cfsa-page .ca-orbit { width: 370px; height: 370px; margin: -185px 0 0 -185px; }
  .cfsa-page .ca-ring-dashed { width: 280px; height: 280px; margin: -140px 0 0 -140px; }
}
@media (max-width: 620px) {
  .cfsa-page .ca-adv-grid { grid-template-columns: 1fr; grid-template-areas: "center" "left" "right"; }
  .cfsa-page .ca-adv-center { height: 340px; }
  .cfsa-page .ca-orbit { display: none; }
  .cfsa-page .ca-ring-dashed { width: 268px; height: 268px; margin: -134px 0 0 -134px; }
}

/* ----- core workflows ----- */
@media (max-width: 980px) {
  .cfsa-page .ca-wf-layout { grid-template-columns: 1fr; }
  .cfsa-page .ca-wf-tabs { position: static; flex-direction: row; overflow-x: auto; padding-bottom: 6px; }
  .cfsa-page .ca-wf-tab { flex: none; }
  .cfsa-page .ca-wf-chev { display: none; }
}
@media (max-width: 760px) {
  .cfsa-page .ca-wf-content { grid-template-columns: 1fr; }
  .cfsa-page .ca-showcase { padding: 18px 18px 34px; }
  .cfsa-page .ca-wf-stage { padding: 14px 14px 24px; }
}
@media (max-width: 700px) {
  .cfsa-page .ca-phone { position: relative; right: auto; bottom: auto; margin: -34px auto 0; }
}
@media (max-width: 520px) {
  .cfsa-page .ca-check-list { grid-template-columns: 1fr; }
  .cfsa-page .ca-wf-actions { flex-direction: column; align-items: stretch; }
  .cfsa-page .ca-wf-actions .ca-btn { width: 100%; }
  .cfsa-page .ca-sb-lower { grid-template-columns: 1fr; justify-items: center; }
}

/* ----- use cases ----- */
@media (max-width: 980px) {
  .cfsa-page .ca-uc-card { grid-template-columns: 1fr; gap: 30px; padding: 30px; }
  .cfsa-page .ca-uc-visual { min-height: 300px; }
}
@media (max-width: 560px) {
  .cfsa-page .ca-uc-card { padding: 22px; }
  .cfsa-page .ca-uc-tab { padding: 10px 16px; font-size: 0.82rem; }
}

/* ----- process ----- */
@media (max-width: 880px) {
  .cfsa-page .ca-how-step { grid-template-columns: 1fr; gap: 12px; padding-bottom: 20px; }
  .cfsa-page .ca-how-rail { padding-top: 0; }
  .cfsa-page .ca-how-card { padding: 18px 20px; }
  .cfsa-page .ca-how-txt p { padding-right: 0; }
}
@media (max-width: 560px) {
  .cfsa-page .ca-how-num { width: 40px; height: 40px; font-size: 0.9rem; }
  .cfsa-page .ca-how-steps::before { left: 19px; }
  .cfsa-page .ca-how-card::after { display: none; }
}

/* ----- impact + team cards ----- */
@media (max-width: 1020px) {
  .cfsa-page .ca-cards4 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .cfsa-page .ca-cards4 { grid-template-columns: 1fr; }
}

/* ----- cta / footer ----- */
@media (max-width: 520px) {
  .cfsa-page .ca-cta-actions { flex-direction: column; align-items: stretch; }
  .cfsa-page .ca-cta-actions .ca-btn { width: 100%; }
}
@media (max-width: 880px) {
  .cfsa-page .ca-footer-top { grid-template-columns: 1fr 1fr; }
  .cfsa-page .ca-footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 560px) {
  .cfsa-page .ca-footer-top { grid-template-columns: 1fr; gap: 30px; }
  .cfsa-page .ca-footer-bar { flex-direction: column; align-items: flex-start; gap: 8px; }
}

/* ----- reduced motion ----- */
@media (prefers-reduced-motion: reduce) {
  .cfsa-page * { animation: none !important; transition: none !important; }
}

